create or replace function private.refresh_qi_profile(p_uid uuid,p_channel text)returns numeric language plpgsql security definer set search_path='' as $$declare p private.player_progression_states;c private.player_cave_states;w private.player_resource_wallets;profile jsonb;core jsonb;comprehension numeric:=5;base_rate numeric;cycle_bonus numeric;cave_bonus numeric;final_rate numeric;begin select * into p from private.player_progression_states where user_id=p_uid and channel=p_channel;select * into c from private.player_cave_states where user_id=p_uid and channel=p_channel;select * into w from private.player_resource_wallets where user_id=p_uid and channel=p_channel for update;if p.user_id is null or w.user_id is null then return 0;end if;profile:=coalesce(w.earning_profile,'{}'::jsonb);begin core:=private.server_base_core(p_uid,p_channel);comprehension:=coalesce((core->>'comprehension')::numeric,5)+case when private.server_all_books_mastered(p_uid,p_channel)then 500 else 0 end;exception when others then comprehension:=5;end;base_rate:=case when p.cultivation_awakened and p.spirit_path_opened then floor((10+floor(2+3*sqrt(greatest(0,comprehension-5))))*private.path_efficiency(p.spirit_level))else 0 end;cycle_bonus:=case p.qi_cycle when'small'then .08+least(8,p.qi_mark_small)*.0075 when'origin'then .04 else .02 end;cave_bonus:=case when c.user_id is not null and c.cultivation_enabled and c.spirit_path_opened then .08+c.cultivation_level*.02 else 0 end;final_rate:=floor(base_rate*(1+cycle_bonus)*(1+cave_bonus));profile:=profile||jsonb_build_object('base_cultivation_rate',base_rate::text,'qi_cycle_bonus',cycle_bonus::text,'cave_cultivation_bonus',cave_bonus::text,'cultivation_rate',final_rate::text);update private.player_resource_wallets set earning_profile=profile,updated_at=now()where user_id=p_uid and channel=p_channel;return final_rate;end$$;

create or replace function private.refresh_resource_profile_authoritative(p_uid uuid,p_channel text)returns jsonb language plpgsql security definer set search_path='' as $$declare p private.player_progression_states;c private.player_cave_states;w private.player_resource_wallets;profile jsonb;core jsonb;fortune numeric:=5;pool_level integer;pool_bonus numeric;sword_base numeric;sword_bonus numeric;begin perform private.refresh_qi_profile(p_uid,p_channel);select * into p from private.player_progression_states where user_id=p_uid and channel=p_channel;select * into c from private.player_cave_states where user_id=p_uid and channel=p_channel;select * into w from private.player_resource_wallets where user_id=p_uid and channel=p_channel for update;if p.user_id is null or w.user_id is null then raise exception '伺服器資源狀態尚未建立';end if;profile:=coalesce(w.earning_profile,'{}'::jsonb);begin core:=private.server_base_core(p_uid,p_channel);fortune:=coalesce((core->>'fortune')::numeric,5)+case when private.server_all_books_mastered(p_uid,p_channel)then 500 else 0 end;exception when others then fortune:=5;end;pool_level:=coalesce(c.spirit_pool_level,1);pool_bonus:=least(greatest(pool_level-1,0),9)*2+least(greatest(pool_level-10,0),10)*3+greatest(pool_level-20,0)*4;sword_base:=case when p.cultivation_awakened and p.sword_path_opened then floor(12.5*private.path_efficiency(p.sword_level))else 0 end;sword_bonus:=case when c.user_id is not null and c.sword_enabled and c.sword_path_opened and c.has_sword_embryo then .08+c.sword_level*.02 else 0 end;profile:=profile||jsonb_build_object('base_sword_rate',sword_base::text,'cave_sword_bonus',sword_bonus::text,'sword_rate',floor(sword_base*(1+sword_bonus))::text,'pool_bonus',pool_bonus::text,'aura_rate',greatest(1,floor(5+pool_bonus+2.5*sqrt(greatest(0,fortune))))::text,'aura_capacity',floor(20000*power(pool_level::numeric,1.35))::text,'food_workers',least(coalesce(c.worker_food,0),floor(coalesce(c.food_area_level,1)*3.5)::integer),'wood_workers',least(coalesce(c.worker_wood,0),coalesce(c.wood_area_level,1)*2),'iron_workers',least(coalesce(c.worker_iron,0),coalesce(c.iron_area_level,1)),'food_capacity',(180::numeric*power(coalesce(c.food_area_level,1),2)-180*coalesce(c.food_area_level,1)+4800)::text,'wood_capacity',(120::numeric*power(coalesce(c.wood_area_level,1),2)-120*coalesce(c.wood_area_level,1)+720)::text,'iron_capacity',(60::numeric*power(coalesce(c.iron_area_level,1),2)-60*coalesce(c.iron_area_level,1)+360)::text);update private.player_resource_wallets set earning_profile=profile,updated_at=now()where user_id=p_uid and channel=p_channel;return profile;end$$;

create or replace function public.player_new_character_initialize_v2(p_channel text,p_name text,p_origin text)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());result jsonb;identity jsonb;preseed boolean;begin if uid is null then raise exception '需要重新登入';end if;if p_origin not in('家族子弟','流浪孤兒','亡命草寇','深山獵戶','寒窗學子')then raise exception '出身資料不正確';end if;select exists(select 1 from private.player_resource_wallets where user_id=uid and channel=p_channel)or exists(select 1 from private.player_progression_states where user_id=uid and channel=p_channel)or exists(select 1 from private.player_body_states where user_id=uid and channel=p_channel)or exists(select 1 from private.player_cave_states where user_id=uid and channel=p_channel)or exists(select 1 from private.player_identity_states where user_id=uid and channel=p_channel)or exists(select 1 from private.player_permanent_consumable_effects where user_id=uid and channel=p_channel)or exists(select 1 from private.player_art_profiles where user_id=uid and channel=p_channel)or exists(select 1 from private.player_equipment_profiles where user_id=uid and channel=p_channel)into preseed;if preseed and not exists(select 1 from private.player_states where user_id=uid and channel=p_channel)then raise exception '偵測到不完整的預載角色資料，請建立新的登入工作階段';end if;perform set_config('app.server_character_initialize','1',true);result:=public.player_new_character_initialize(p_channel,p_name);identity:=public.player_identity_bootstrap(p_channel,p_origin);perform private.refresh_resource_profile_authoritative(uid,p_channel);return result||jsonb_build_object('identity',identity);end$$;
